"""Polynomial-time reduction from Vertex Cover to Set Cover.

Vertex Cover instance: {"n": n, "edges": [[u, v], ...], "k": k}
Set Cover instance:    {"universe_size": u, "sets": [[element, ...], ...], "k": k}

Reduction: the universe is the set of edges (element i <-> edges[i]).  For each
vertex v we build the set of edges incident to v.  A set of vertices covers all
edges exactly when the corresponding collection of sets covers the universe, so
the same budget k works.
"""

from __future__ import annotations

from typing import Any


def reduce(instance: dict[str, Any]) -> dict[str, Any]:
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]

    # One set per vertex: the indices of the edges incident to that vertex.
    sets: list[list[int]] = [[] for _ in range(n)]
    for index, (u, v) in enumerate(edges):
        sets[u].append(index)
        sets[v].append(index)

    return {"universe_size": len(edges), "sets": sets, "k": k}
EOF
cat > solvers.py <<'EOF'
"""Brute-force solvers for Vertex Cover and Set Cover (small instances)."""

from __future__ import annotations

from itertools import combinations


def vertex_cover_answer(instance: dict) -> bool:
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]
    if k < 0:
        return False
    # Minimum vertex cover size by brute force over subsets.
    for size in range(0, n + 1):
        if size > k:
            break
        for subset in combinations(range(n), size):
            chosen = set(subset)
            if all(u in chosen or v in chosen for u, v in edges):
                return True
    return False


def set_cover_answer(instance: dict) -> bool:
    u = instance["universe_size"]
    sets = instance["sets"]
    k = instance["k"]
    if k < 0:
        return False
    if u == 0:
        return True
    universe = set(range(u))
    for size in range(0, min(k, len(sets)) + 1):
        for combo in combinations(range(len(sets)), size):
            covered: set[int] = set()
            for i in combo:
                covered.update(sets[i])
            if covered >= universe:
                return True
    return False
EOF
echo done"}

